{"id":"49b12241-8bcd-4952-a18f-4477847cc557","inserted_at":"2026-06-23T13:39:16.845252+00:00","updated_at":"2026-06-23T13:39:16.845252+00:00","type":"sql","name":"Untitled query","description":"","content":{"sql":"-- MIGRATION: Media, Ticker and Whitelabel Config\r\n\r\n-- 1. Aggiungere le colonne mancanti alla tabella POIS\r\nALTER TABLE public.pois\r\nADD COLUMN IF NOT EXISTS image_url TEXT,\r\nADD COLUMN IF NOT EXISTS description TEXT;\r\n\r\n-- 2. Aggiungere la colonna Ticker alla tabella TERRITORIES\r\nALTER TABLE public.territories\r\nADD COLUMN IF NOT EXISTS ticker_text TEXT;\r\n\r\n-- 3. Inserimento del Ticker iniziale (Mockup) per il territorio di Taranto\r\nUPDATE public.territories\r\nSET ticker_text = '🍃 TARANTO COMMUNITY TODAY: 1.240 Liters saved • 45kg Plastic • 12kg CO₂'\r\nWHERE name ILIKE 'Taranto';\r\n\r\n-- 4. Creazione sicura del bucket Storage (se non esiste)\r\nINSERT INTO storage.buckets (id, name, public)\r\nVALUES ('loto-media', 'loto-media', true)\r\nON CONFLICT (id) DO NOTHING;\r\n\r\n-- 5. Policy Storage per permettere la lettura pubblica\r\nCREATE POLICY \"Public Access\"\r\nON storage.objects FOR SELECT\r\nUSING ( bucket_id = 'loto-media' );\r\n\r\n-- 6. Policy Storage per permettere il caricamento\r\nCREATE POLICY \"Enable insert for all users\"\r\nON storage.objects FOR INSERT\r\nWITH CHECK ( bucket_id = 'loto-media' );\r\n\r\nCREATE POLICY \"Enable update for all users\"\r\nON storage.objects FOR UPDATE\r\nUSING ( bucket_id = 'loto-media' );","content_id":"49b12241-8bcd-4952-a18f-4477847cc557","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
